'use strict';

// MODULES //

var ack = require( './ack' );
var app = require( './app' );
var events = require( './events' );
var home = require( './home' );
var landing = require( './landing' );
var ping = require( './ping' );
var schema = require( './schema' );
var status = require( './status' ); // eslint-disable-line stdlib/no-redeclare

var lilgui = require( './vendored/lilgui' );
var vega = require( './vendored/vega' );

var axesTitle = require( './config/axes/title' );
var background = require( './config/background' );
var description = require( './config/description' );
var height = require( './config/height' );
var paddingBottom = require( './config/padding/bottom' );
var paddingLeft = require( './config/padding/left' );
var paddingRight = require( './config/padding/right' );
var paddingTop = require( './config/padding/top' );
var titleAlign = require( './config/title/align' );
var titleAnchor = require( './config/title/anchor' );
var titleAngle = require( './config/title/angle' );
var titleBaseline = require( './config/title/baseline' );
var titleColor = require( './config/title/color' );
var titleDX = require( './config/title/dx' );
var titleDY = require( './config/title/dy' );
var titleFont = require( './config/title/font' );
var titleFontSize = require( './config/title/font-size' );
var titleFontStyle = require( './config/title/font-style' );
var titleFontWeight = require( './config/title/font-weight' );
var titleFrame = require( './config/title/frame' );
var titleLimit = require( './config/title/limit' );
var titleLineHeight = require( './config/title/line-height' );
var titleOffset = require( './config/title/offset' );
var titleOrient = require( './config/title/orient' );
var titleSubtitle = require( './config/title/subtitle' );
var titleSubtitleColor = require( './config/title/subtitle-color' );
var titleSubtitleFont = require( './config/title/subtitle-font' );
var titleSubtitleFontSize = require( './config/title/subtitle-font-size' );
var titleSubtitleFontStyle = require( './config/title/subtitle-font-style' );
var titleSubtitleFontWeight = require( './config/title/subtitle-font-weight' );
var titleSubtitleLineHeight = require( './config/title/subtitle-line-height' );
var titleSubtitlePadding = require( './config/title/subtitle-padding' );
var titleText = require( './config/title/text' );
var width = require( './config/width' );


// MAIN //

/**
* Registers routes.
*
* @private
* @param {Object} router - router instance
*/
function register( router ) {
	// Status routes:
	router.route( status() );                     // /status
	router.route( ping() );                       // /ping

	// Static files:
	router.route( vega() );                       // /vendored/vega.min.js
	router.route( lilgui() );                     // /vendored/lil_gui.min.js
	router.route( app() );                        // /app.js

	// Landing page:
	router.route( home() );                       // /
	router.route( landing() );                    // /index.html

	// Server-sent events:
	router.route( events() );                     // /events
	router.route( ack() );                        // /ack

	// Specification:
	router.route( schema() );                     // /schema

	router.route( axesTitle() );                  // /config/axes/:axis/title

	router.route( background() );                 // /config/background

	router.route( description() );                // /config/description

	router.route( height() );                     // /config/height

	router.route( paddingBottom() );              // /config/padding/bottom
	router.route( paddingLeft() );                // /config/padding/left
	router.route( paddingRight() );               // /config/padding/right
	router.route( paddingTop() );                 // /config/padding/top

	router.route( titleAlign() );                 // /config/title/align
	router.route( titleAnchor() );                // /config/title/anchor
	router.route( titleAngle() );                 // /config/title/angle
	router.route( titleBaseline() );              // /config/title/baseline
	router.route( titleColor() );                 // /config/title/color
	router.route( titleDX() );                    // /config/title/dx
	router.route( titleDY() );                    // /config/title/dy
	router.route( titleFont() );                  // /config/title/font
	router.route( titleFontSize() );              // /config/title/fontSize
	router.route( titleFontStyle() );             // /config/title/fontStyle
	router.route( titleFontWeight() );            // /config/title/fontWeight
	router.route( titleFrame() );                 // /config/title/frame
	router.route( titleLimit() );                 // /config/title/limit
	router.route( titleLineHeight() );            // /config/title/lineHeight
	router.route( titleOffset() );                // /config/title/offset
	router.route( titleOrient() );                // /config/title/orient
	router.route( titleSubtitle() );              // /config/title/subtitle
	router.route( titleSubtitleColor() );         // /config/title/subtitleColor
	router.route( titleSubtitleFont() );          // /config/title/subtitleFont
	router.route( titleSubtitleFontSize() );      // /config/title/subtitleFontSize
	router.route( titleSubtitleFontStyle() );     // /config/title/subtitleFontStyle
	router.route( titleSubtitleFontWeight() );    // /config/title/subtitleFontWeight
	router.route( titleSubtitleLineHeight() );    // /config/title/subtitleLineHeight
	router.route( titleSubtitlePadding() );       // /config/title/subtitlePadding
	router.route( titleText() );                  // /config/title/text

	router.route( width() );                      // /config/width
}


// EXPORTS //

module.exports = register;
